1. @page "/board"
2. @rendermode InteractiveServer
3. @inject ITaskService TaskService
4. 
5. <PageTitle>Kanban Board</PageTitle>
6. 
7. <h1>Project Board</h1>
8. 
9. @if (isLoading)
10. {
11.     <p class="loading">Loading tasks...</p>
12. }
13. else if (errorMessage is not null)
14. {
15.     <p class="error">@errorMessage</p>
16. }
17. else
18. {
19.     <BoardStats Total="allTasks.Count"
20.                 ToDo="todoTasks.Count"
21.                 InProgress="inProgressTasks.Count"
22.                 Done="doneTasks.Count"
23.                 Overdue="allTasks.Count(t => t.DueDate < DateTime.Today)" />
24. 
25.     <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />
26. 
27.     <div class="kanban-board">
28.         <KanbanColumn ColumnName="To Do"
29.                       Tasks="FilteredTasks(todoTasks)"
30.                       CanMoveLeft="false"
31.                       CanMoveRight="true"
32.                       OnMoveRight="@((task) => MoveTask(task, StatusInProgress))"
33.                       OnAddTask="@((t) => AddTask(t, StatusToDo))" />
34. 
35.         <KanbanColumn ColumnName="In Progress"
36.                       Tasks="FilteredTasks(inProgressTasks)"
37.                       CanMoveLeft="true"
38.                       CanMoveRight="true"
39.                       OnMoveLeft="@((task) => MoveTask(task, StatusToDo))"
40.                       OnMoveRight="@((task) => MoveTask(task, StatusDone))"
41.                       OnAddTask="@((t) => AddTask(t, StatusInProgress))" />
42. 
43.         <KanbanColumn ColumnName="Done"
44.                       Tasks="FilteredTasks(doneTasks)"
45.                       CanMoveLeft="true"
46.                       CanMoveRight="false"
47.                       OnMoveLeft="@((task) => MoveTask(task, StatusInProgress))"
48.                       OnAddTask="@((t) => AddTask(t, StatusDone))" />
49.     </div>
50. }
51. 
52. @code {
53.     private const string StatusToDo = "To Do";
54.     private const string StatusInProgress = "In Progress";
55.     private const string StatusDone = "Done";
56. 
57.     private List<TaskItem> allTasks = new();
58.     private bool isLoading = true;
59.     private string? errorMessage;
60.     private string searchText = string.Empty;
61. 
62.     private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == StatusToDo).ToList();
63.     private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == StatusInProgress).ToList();
64.     private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == StatusDone).ToList();
65. 
66.     private List<TaskItem> FilteredTasks(List<TaskItem> tasks)
67.     {
68.         if (string.IsNullOrWhiteSpace(searchText))
69.             return tasks;
70.         return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
71.     }
72. 
73.     protected override async Task OnInitializedAsync()
74.     {
75.         try
76.         {
77.             allTasks = await TaskService.GetAllTasksAsync();
78.         }
79.         catch (Exception ex)
80.         {
81.             errorMessage = $"Failed to load tasks: {ex.Message}";
82.         }
83.         finally
84.         {
85.             isLoading = false;
86.         }
87.     }
88. 
89.     private void OnSearchChanged(string value)
90.     {
91.         searchText = value;
92.     }
93. 
94.     private async Task MoveTask(TaskItem task, string newStatus)
95.     {
96.         try
97.         {
98.             await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
99.             var index = allTasks.FindIndex(t => t.Id == task.Id);
100.             if (index >= 0)
101.             {
102.                 allTasks[index] = task with { Status = newStatus };
103.             }
104.         }
105.         catch (Exception ex)
106.         {
107.             errorMessage = $"Failed to move task: {ex.Message}";
108.         }
109.     }
110. 
111.     private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) newTask, string status)
112.     {
113.         try
114.         {
115.             var created = await TaskService.CreateTaskAsync(newTask.Title, newTask.Assignee, newTask.Priority, newTask.DueDate);
116.             allTasks.Add(created);
117.         }
118.         catch (Exception ex)
119.         {
120.             errorMessage = $"Failed to create task: {ex.Message}";
121.         }
122.     }
123. }
