 @page "/board"
 @rendermode InteractiveServer
 @inject ITaskService TaskService

 <PageTitle>Kanban Board</PageTitle>

 <h1>Project Board</h1>

 @if (isLoading)
 {
     <p class="loading">Loading tasks...</p>
 }
 else if (errorMessage is not null)
 {
     <p class="error">@errorMessage</p>
 }
 else
 {
     <BoardStats Total="allTasks.Count"
                 ToDo="todoTasks.Count"
                 InProgress="inProgressTasks.Count"
                 Done="doneTasks.Count"
                 Overdue="allTasks.Count(t => t.DueDate < DateTime.Today)" />

     <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />

     <div class="kanban-board">
         <KanbanColumn ColumnName="To Do"
                       Tasks="FilteredTasks(todoTasks)"
                       CanMoveLeft="false"
                       CanMoveRight="true"
                       OnMoveRight="@((task) => MoveTask(task, StatusInProgress))"
                       OnAddTask="@((t) => AddTask(t, StatusToDo))" />

         <KanbanColumn ColumnName="In Progress"
                       Tasks="FilteredTasks(inProgressTasks)"
                       CanMoveLeft="true"
                       CanMoveRight="true"
                       OnMoveLeft="@((task) => MoveTask(task, StatusToDo))"
                       OnMoveRight="@((task) => MoveTask(task, StatusDone))"
                       OnAddTask="@((t) => AddTask(t, StatusInProgress))" />

         <KanbanColumn ColumnName="Done"
                       Tasks="FilteredTasks(doneTasks)"
                       CanMoveLeft="true"
                       CanMoveRight="false"
                       OnMoveLeft="@((task) => MoveTask(task, StatusInProgress))"
                       OnAddTask="@((t) => AddTask(t, StatusDone))" />
     </div>
 }

 @code {
     private const string StatusToDo = "To Do";
     private const string StatusInProgress = "In Progress";
     private const string StatusDone = "Done";

     private List<TaskItem> allTasks = new();
     private bool isLoading = true;
     private string? errorMessage;
     private string searchText = string.Empty;

     private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == StatusToDo).ToList();
     private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == StatusInProgress).ToList();
     private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == StatusDone).ToList();

     private List<TaskItem> FilteredTasks(List<TaskItem> tasks)
     {
         if (string.IsNullOrWhiteSpace(searchText))
             return tasks;
         return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
     }

     protected override async Task OnInitializedAsync()
     {
         try
         {
             allTasks = await TaskService.GetAllTasksAsync();
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to load tasks: {ex.Message}";
         }
         finally
         {
             isLoading = false;
         }
     }

     private void OnSearchChanged(string value)
     {
